# -*- coding: utf-8 -*-
"""Genera FICHA_A2.md: ficha maestra v2 del Anexo 2 (supera a la ficha anterior donde difieren)."""
import m2, expand as X
from m2 import cop, pct, mm
w = []
A = w.append
A("# FICHA MAESTRA v2 DEL ANEXO 2 (fuente única de cifras; prevalece sobre la ficha anterior)\n")
A("Esta ficha incorpora los términos de referencia (TdR v1.6, convocatoria 56) que se aportaron después de la corrida anterior. Donde difiere de RAIZ/maestro/FICHA_MAESTRA.md o de los capítulos de RAIZ/caps/, prevalece esta ficha.\n")
A("## 1. Identidad\n")
A(f"- Título ({len(m2.IDENT['titulo'])} caracteres con espacios): {m2.IDENT['titulo']}")
A(f"- Proceso: {m2.IDENT['proceso']}. Objeto: {m2.IDENT['objeto']}. Localización: {m2.IDENT['localizacion']}.")
A("- Convocatoria: 56, Convocatoria de emergencia para la recuperación y generación de capacidades transformadoras, en el marco del Decreto 1414 de 17 de septiembre de 2026. Cierre de presentación: 3 de noviembre de 2026, 4:00 p. m.")
A("- Línea temática principal: 5.1. Ciencia, tecnología e innovación para la gestión anticipada del riesgo y la seguridad de las regiones; subnumerales 5.1.1 (monitoreo inteligente, observación territorial y alerta temprana) y 5.1.2 (modelación avanzada, gemelos digitales y analítica predictiva). Sin línea secundaria.")
A("- Territorio: Caldas (región Eje Cafetero), Cundinamarca (Centro Oriente) y Valle del Cauca (Pacífico); verificar con el Anexo 8. 12 municipios (4 por departamento; nombres por diligenciar). Nodos: Caldas 33, Cundinamarca 34, Valle del Cauca 33.")
A("- Evento: terremoto (Decreto 1261 de 2026, modificado por el Decreto 1348 de 2026). Territorio y alianza son supuestos de trabajo por instrucción del usuario; no hay reportes oficiales de afectación en los archivos.")
A("- Duración: 24 meses (104 semanas). Red: TRL de entrada 4; TRL comprometido al cierre 8; piso TRL 7 al mes 19. La evidencia del TRL 8 es el ensayo independiente y la evaluación externa del mes 23 (hito H7). Gemelo predictivo de demolición: TRL 3 de entrada y TRL 6 al cierre, con validación en al menos 6 eventos reales.")
A("- Alianza (numeral 3 de los TdR): cuatro integrantes. Entidad proponente y ejecutora = IES con acreditación de alta calidad (supuesto), que aloja y valida el laboratorio de modelación; aliado 1 = municipio de un departamento afectado (usuario del laboratorio y custodio con su comité); aliado 2 = actor del SNCTI con reconocimiento vigente de MinCiencias (estancias, formación y validación metodológica); aliado 3 = empresa tecnológica (plataforma, nube y actor del sector productivo). Nombres por diligenciar. Cada integrante aporta contrapartida cuantificada; el valor del aporte del actor del SNCTI está por certificar. El municipio aliado no puede figurar también como beneficiario; si coincide con la jurisdicción de alguno de los 15 comités, ese comité se sustituye por otro de la misma jurisdicción.")
A("- Beneficiarios: 15 comités de gestión del riesgo (12 municipales y 3 departamentales), 150 funcionarios (supuesto), operarios de remoción, población expuesta, autoridades ambientales.\n")
A("## 2. Solución\n")
A("Red de 100 nodos hoja de medición de PM2,5 y PM10 (sensor óptico de bajo costo con temperatura y humedad), 10 gateways y 3 monitores gravimétricos de referencia (uno por departamento) para colocalización. Los nodos transmiten por LoRa al gateway; el gateway aplica el modelo de corrección (humedad, temperatura, fracción gruesa) y reenvía por red celular con enlace satelital de respaldo y almacenamiento local de 7 días; nodos con autonomía mínima de 14 días sin sol; la nube aloja el gemelo digital, la base de datos y el tablero con el índice local y el protocolo de alerta. Custodia distribuida por componente y por tramo, con cláusula de apertura. Metas técnicas: R² ≥ 0,70 y NRMSE ≤ 30 % frente a la referencia (guía de la EPA de 2021 como ancla informativa); pendiente 0,65–1,35; sesgo entre −5,0 y 5,0 µg/m³; disponibilidad mensual ≥ 90 %; pérdida de paquetes ≤ 10 %. NMAE ≤ 15 % es aspiración. La línea base de error se mide en el tramo 1.\n\nLaboratorio de modelación y gemelo predictivo de demolición (dentro de los objetivos 1, 2 y 3; sin objetivo adicional): alojado en la IES y validado por ella, con servidor de cómputo, 4 estaciones meteorológicas, dron con LiDAR y GNSS y 2 monitores portátiles. Cadena de cinco bloques: inventario de entrada, emisión (factores AP-42 13.2.3 de la EPA ajustados con polvo local), dispersión (AERMOD de tamizaje y CFD entre edificios), modelo sustituto supervisado y evaluación previa con escenarios de control. Validación con 9 campañas y al menos 6 eventos válidos (al menos 2 por departamento), validación cruzada dejando un evento fuera, FAC2 ≥ 0,5 y sesgo fraccional absoluto ≤ 0,3; línea base: tamizaje con factores genéricos; verificador independiente. El resultado es una evaluación previa y no una autorización; no se afirman efectos en la salud.\n")
A("## 3. Objetivos\n")
A(f"- Objetivo general: {m2.M0.OG}")
for o in m2.M0.OE: A(f"- {o['id']}: {o['texto']} Meta: {o['meta']}.")
A("\n## 4. Tramos\n")
A("| Tramo | Meses | Nodos | Gateways | Compra nodos | Compra gateways | Compuerta |\n| --- | --- | --- | --- | --- | --- | --- |")
for t in m2.M0.TRAMOS: A(f"| {t['nombre']} | {t['m_ini']}–{t['m_fin']} | {t['nodos']} | {t['gateways']} | {t['compra_nodos']} | {t['compra_gw']} | {t['compuerta']} (mes {t['mes_compuerta']}) |")
A("\nCompuertas: C1 (mes 12) libera el tramo 2 si R² ≥ 0,70 y NRMSE ≤ 30 % en el piloto y si al menos 50 % de los comités del tramo 1 usa el tablero. C2 (mes 17) libera el tramo 3 con los mismos umbrales en los tres departamentos, disponibilidad ≥ 90 % y convenios de custodia con partida. C3 (mes 24) cierra y transfiere. Las compuertas no reducen el alcance de 100 nodos y 10 gateways: condicionan la secuencia y activan un ciclo de corrección del modelo.\n")
A("## 5. Presupuesto v2 (SGR)\n")
A(f"- Valor solicitado al SGR: {cop(m2.SGR)} ({pct(m2.SGR / m2.IDENT['tope_cop'])} del tope de {cop(m2.IDENT['tope_cop'])}; no se solicita la holgura de {cop(m2.IDENT['tope_cop'] - m2.SGR)}).")
A(f"- Contrapartida: {cop(m2.CON)} (efectivo {cop(m2.CON_EFECTIVO)}, {pct(m2.CON_EFECTIVO / m2.SGR, 2)} del SGR; especie {cop(m2.CON - m2.CON_EFECTIVO)}). Total del proyecto: {cop(m2.TOTAL)}.")
A(f"- Transferencia: {cop(m2.TRANSFER)} = {pct(m2.TRANSFER / m2.TOTAL, 2)} del valor total (mínimo 1 %). Movilidad: {cop(m2.MOVILIDAD)} = {pct(m2.MOVILIDAD / m2.SGR, 2)} del SGR (máximo 2 %).")
A("- Sin reserva de contingencia, sin pólizas ni seguros (excluidos por el numeral 14.3 de los TdR). El riesgo se atiende con 20 nodos y 1 gateway de reserva, compras por tramo, compuertas y cotizaciones vigentes.\n")
A("| Rubro del TdR | Valor (COP) | % SGR |\n| --- | --- | --- |")
for k, v in m2.POR_RUBRO.items():
    if v: A(f"| {k} | {cop(v)} | {pct(v / m2.SGR)} |")
A("\n### Líneas de presupuesto SGR\n")
A("| Id | Rubro TdR | Concepto | Unidad | Cant. | Costo unitario | Total | Naturaleza |\n| --- | --- | --- | --- | --- | --- | --- | --- |")
for r in m2.BUD: A(f"| {r['id']} | {r['rubro_tdr']} | {r['concepto']} | {r['unidad']} | {r['cant']:,.0f}".replace(",", ".") + f" | {cop(r['vunit'])} | {cop(r['total'])} | {r['nat']} |")
A("\n### Contrapartida\n")
A("| Id | Aportante | Aporte | Modalidad | Total |\n| --- | --- | --- | --- | --- |")
for r in m2.CONTRA: A(f"| {r['id']} | {r['fuente']} | {r['concepto']} | {'Efectivo' if r['rubro'] == 'Efectivo' else 'Especie'} | {cop(r['total'])} |")
A("\n### Ajustes por los TdR (respecto de la ficha anterior)\n")
A("| Id | Tema | Antes | Después | Fundamento |\n| --- | --- | --- | --- | --- |")
for a in m2.AJUSTES: A(f"| {a['id']} | {a['tema']} | {a['antes']} | {a['despues']} | {a['base']} |")
A("\n- AJ-07 TRL: de TRL 4 a 7 (ficha anterior) a TRL 4 a 8 con piso 7 al mes 19; los TdR valoran el TRL 8 con 8 puntos y el TRL 7 con 3; la evidencia es el ensayo independiente (S08) y la evaluación externa (S07) del mes 23.")
A("- AJ-08 Productos: seis artículos de jóvenes, dos productos de maestría y uno de posdoctorado (9 documentos de investigación) en lugar de 2 artículos; cada persona entrega además un producto de divulgación (numeral 9).")
A("- AJ-09 Alcance integral: se elimina el lenguaje de «opciones de ampliación» posteriores; el proyecto no depende de fases posteriores (numerales 1, 3 y 6).\n")
A(f"## 6. Actividades, periodo y valor ({len(m2.ACTD)} actividades)\n")
A("| N.º | Actividad | OE | Meses | Semanas (inicio–fin) | Holgura | SGR | Contrapartida |\n| --- | --- | --- | --- | --- | --- | --- | --- |")
for a in m2.ACTD.values(): A(f"| {a['id']} | {a['nombre']} | {a['oe']} | M{a['m_ini']}–M{a['m_fin']} | {a['es']}–{a['ef']} | {a['holgura']} | {cop(a['sgr'])} | {cop(a['contra'])} |")
crit = [a["id"] for a in m2.ACTD.values() if a["holgura"] == 0 and a["id"] not in m2.ADM]
